const d   = $input.first().json;
const now = new Date().toLocaleDateString('en-US', { year:'numeric', month:'long', day:'numeric' });

const html = `<!DOCTYPE html>
<html>
<head><meta charset="utf-8"><style>
  body{font-family:Arial,sans-serif;margin:0;padding:0;background:#f1f5f9}
  .wrap{max-width:600px;margin:30px auto;background:#fff;border-radius:10px;overflow:hidden;box-shadow:0 4px 16px rgba(0,0,0,.08)}
  .hdr{background:linear-gradient(135deg,#1e40af,#2563eb);padding:28px 36px;color:#fff}
  .hdr h1{margin:0;font-size:20px;font-weight:700}
  .hdr p{margin:6px 0 0;opacity:.8;font-size:13px}
  .body{padding:36px}
  .reply{font-size:15px;color:#1e293b;line-height:1.75;white-space:pre-wrap;margin-bottom:28px}
  .divider{border:none;border-top:1px solid #e2e8f0;margin:24px 0}
  .original{background:#f8fafc;border-radius:8px;padding:18px 20px}
  .original h4{margin:0 0 10px;font-size:12px;color:#94a3b8;text-transform:uppercase;letter-spacing:.5px}
  .original p{margin:0;font-size:13px;color:#64748b;line-height:1.6;white-space:pre-wrap}
  .footer{background:#f8fafc;padding:16px 36px;text-align:center;font-size:12px;color:#94a3b8;border-top:1px solid #e2e8f0}
</style></head>
<body>
  <div class="wrap">
    <div class="hdr">
      <h1>Re: ${d.subject}</h1>
      <p>Support reply &bull; ${now}</p>
    </div>
    <div class="body">
      <div class="reply">${d.ai_draft}</div>
      <hr class="divider">
      <div class="original">
        <h4>Your original message</h4>
        <p>${d.body_text.substring(0, 500)}${d.body_text.length > 500 ? '...' : ''}</p>
      </div>
    </div>
    <div class="footer">
      <p>Ticket #${d.ticket_id} &bull; Replied ${now}</p>
    </div>
  </div>
</body>
</html>`;

return [{
  json: {
    ...d,
    reply_html:    html,
    reply_subject: 'Re: ' + d.subject,
    replied_at:    new Date().toISOString()
  }
}];
